shellCommands.command:
(npx next start -p 3123 > /tmp/next-start.log 2>&1 &) ; sleep 4; 
echo "=== per-link prefetch (RSC + prefetch headers) ==="; 
curl -s http://localhost:3123/projects/acme -H 'RSC: 1' -H 'Next-Router-Prefetch: 1' -H 'Next-Router-Segment-Prefetch: /_full' -H 'Next-Url: /projects/acme' | tr -d '\0' | grep -oE 'Acme Storefront|Commerce storefront|Loading details|Loading project|Production deployment' | sort | uniq -c;
echo "=== segment prefetch (page segment) ===";
curl -s 'http://localhost:3123/projects/acme' -H 'RSC: 1' -H 'Next-Router-Prefetch: 1' -H 'Next-Router-Segment-Prefetch: /projects/$d$slug/__PAGE__' | tr -d '\0' | grep -oE 'Acme Storefront|Commerce storefront|Loading details|Loading project|Production deployment' | sort | uniq -c;
echo "=== full navigation (RSC, no prefetch) ==="; 
curl -s http://localhost:3123/projects/acme -H 'RSC: 1' | tr -d '\0' | grep -oE 'Acme Storefront|Commerce storefront|Loading details|Loading project|Production deployment' | sort | uniq -c;
pkill -f 'next start' ; true
